Given an array arr of integers of size n. We need to compute the sum of elements from index i to index j. The queries consisting of i and j index values will be executed multiple times.Examples: Input : arr[] = {1, 2, 3, 4, 5}        i = 1, j = 3        i = 2, j = 4Output :  9         12         Input : arr[] = {1, 2, 3, 4, 5}        i = 0, j = 4         i = 1, j = 2 Output : 15          5Try It Yourself[Naive Solution] - Simple Sum - O(n) for Every Query and O(1) SpaceA Simple Solution is to compute the sum for every query.
            C++14

    // C++ program to find sum between two indexes
#include <bits/stdc++.h>
using namespace std;

// Function to compute sum in given range
int rangeSum(const vector<int>& arr, int i, int j) {
    int sum = 0;

    // Compute sum from i to j
    for (int k = i; k <= j; k++) {
        sum += arr[k];
    }

    return sum;
}

// Driver code
int main() {
    vector<int> arr = { 1, 2, 3, 4, 5 };
    cout << rangeSum(arr, 1, 3) << endl;
    cout << rangeSum(arr, 2, 4) << endl;
    return 0;
}


